
import streamlit as st
import pandas as pd
import numpy as np
from collections import Counter
import base64, io

st.set_page_config(page_title="Hızlı On - Ritim Davranışı Uzmanı", layout="wide")
st.title("Hızlı On – Ritim Davranışı Uzmanı")
st.caption("14 günlük gömülü veri: 25.08.2026–07.09.2026 | 3.038 çekiliş | 1–80")

DATA_B64 = """"""

@st.cache_data
def load_embedded():
    text = base64.b64decode(DATA_B64.encode("ascii")).decode("utf-8")
    rows = []
    for line in text.splitlines():
        line=line.strip()
        if not line:
            continue
        p=line.split(";")
        if len(p)!=3:
            continue
        draw=int(p[0])
        dt=pd.to_datetime(p[1], dayfirst=True, errors="coerce")
        nums=sorted(set(int(x) for x in p[2].split(",") if x.strip()))
        if pd.isna(dt) or len(nums)!=20:
            continue
        rows.append((draw,dt,nums))
    return pd.DataFrame(rows,columns=["draw","dt","nums"]).sort_values("dt").reset_index(drop=True)

@st.cache_data
def build_matrix(df):
    X=np.zeros((len(df),80),dtype=np.uint8)
    for i,nums in enumerate(df["nums"]):
        X[i,np.array(nums)-1]=1
    return X

@st.cache_data
def gap_sequences(df):
    X=build_matrix(df)
    seq={}
    rows=[]
    for n in range(1,81):
        pos=np.flatnonzero(X[:,n-1])
        gaps=np.diff(pos)
        seq[n]=gaps.tolist()
        for i,g in enumerate(gaps):
            rows.append((n,int(g),int(pos[i]),int(pos[i+1])))
    return pd.DataFrame(rows,columns=["number","gap","from_idx","to_idx"]),seq

def runs_for_gap(gaps,g):
    runs=[]
    i=0
    while i<len(gaps):
        if gaps[i]!=g:
            i+=1
            continue
        j=i+1
        while j<len(gaps) and gaps[j]==g:
            j+=1
        runs.append(j-i)
        i=j
    return runs

@st.cache_data
def continuation_table(df,max_gap=100,max_reps=8):
    X=build_matrix(df)
    rows=[]
    for n in range(1,81):
        pos=np.flatnonzero(X[:,n-1])
        gaps=np.diff(pos)
        for g in range(1,max_gap+1):
            for r in range(1,max_reps+1):
                total=hit=0
                if len(gaps)>r:
                    for i in range(r-1,len(gaps)-1):
                        if np.all(gaps[i-r+1:i+1]==g):
                            total+=1
                            hit+=int(gaps[i+1]==g)
                rows.append((n,g,r,total,hit,hit/total if total else np.nan))
    return pd.DataFrame(rows,columns=["number","gap","repeats","opportunities","continued","rate"])

@st.cache_data
def h_pattern_panel(df,max_h=100):
    X=build_matrix(df)
    rows=[]
    for t in range(max_h,len(df)):
        cur=X[t]
        for n in range(1,81):
            hist = X[t-max_h:t, n-1]
            last_seen = np.flatnonzero(hist)
            gap = (max_h - last_seen[-1]) if len(last_seen) else max_h+1
            f8=int(hist[-8:].sum())
            f24=int(hist[-24:].sum())
            f50=int(hist[-50:].sum())
            rows.append((t,df.at[t,"dt"],n,int(cur[n-1]),gap,f8,f24,f50))
    return pd.DataFrame(rows,columns=["t","dt","number","real20","gap_since","f8","f24","f50"])

@st.cache_data
def motif_counts(df,max_len=5):
    _,seq=gap_sequences(df)
    c={L:Counter() for L in range(2,max_len+1)}
    for n,gaps in seq.items():
        for L in range(2,max_len+1):
            for i in range(len(gaps)-L+1):
                c[L][tuple(gaps[i:i+L])] += 1
    return c

df=load_embedded()
X=build_matrix(df)
gap_df,seq=gap_sequences(df)

c1,c2,c3,c4=st.columns(4)
c1.metric("Çekiliş",f"{len(df):,}")
c2.metric("Gün",df["dt"].dt.date.nunique())
c3.metric("İlk çekiliş",df["draw"].iloc[0])
c4.metric("Son çekiliş",df["draw"].iloc[-1])

tabs=st.tabs([
    "Genel Gap",
    "Sayı Yaşamı",
    "Ritim Devamı",
    "18 / 23 / 57",
    "Değişken Motifler",
    "H1–H100",
    "REAL20 / NEGATIVE60",
    "Walk-Forward"
])

with tabs[0]:
    st.subheader("Gerçek ardışık görünme aralıkları")
    m=st.slider("Maksimum gap",10,100,40)
    z=gap_df[gap_df.gap<=m].groupby("gap").size().reset_index(name="count")
    st.bar_chart(z.set_index("gap"))
    st.dataframe(z,use_container_width=True)

with tabs[1]:
    st.subheader("1–80 sayı bazlı yaşam ritmi")
    n=st.number_input("Sayı",1,80,23,1,key="numlife")
    gaps=seq[int(n)]
    cc=Counter(gaps)
    stat=[]
    for g in sorted(cc):
        runs=runs_for_gap(gaps,g)
        stat.append({
            "gap":g,
            "count":cc[g],
            "max_same_gap_run":max(runs) if runs else 0,
            "repeat_run_events":sum(1 for x in runs if x>=2)
        })
    st.dataframe(pd.DataFrame(stat).sort_values(["max_same_gap_run","count"],ascending=False),use_container_width=True)
    st.code(", ".join(map(str,gaps)))

with tabs[2]:
    st.subheader("Aynı ritim devam ediyor mu?")
    max_gap=st.slider("Gap üst sınırı",5,100,30,key="contgap")
    max_rep=st.slider("Tekrar üst sınırı",2,8,6,key="contreps")
    cont=continuation_table(df,max_gap,max_rep)
    glob=cont.groupby(["gap","repeats"],as_index=False).agg(
        opportunities=("opportunities","sum"),
        continued=("continued","sum")
    )
    glob["rate_pct"]=np.where(glob.opportunities>0,100*glob.continued/glob.opportunities,np.nan)
    min_support=st.slider("Minimum fırsat",1,100,10)
    show=glob[glob.opportunities>=min_support].copy()
    st.dataframe(show.sort_values(["repeats","rate_pct"],ascending=[False,False]),use_container_width=True)

with tabs[3]:
    st.subheader("18 / 23 / 57 özel kontrol")
    rows=[]
    for g in [18,23,57]:
        z=gap_df[gap_df.gap==g]
        maxrun=0
        rep_events=0
        for n,gaps in seq.items():
            runs=runs_for_gap(gaps,g)
            if runs:
                maxrun=max(maxrun,max(runs))
                rep_events += sum(1 for r in runs if r>=2)
        rows.append({
            "gap":g,
            "total_events":len(z),
            "numbers_seen":z.number.nunique(),
            "max_same_gap_run":maxrun,
            "repeat_run_events":rep_events
        })
    st.dataframe(pd.DataFrame(rows),use_container_width=True)

with tabs[4]:
    st.subheader("Değişken ritim motifleri")
    L=st.slider("Motif uzunluğu",2,5,3)
    motifs=motif_counts(df,5)[L]
    top=pd.DataFrame(
        [(" → ".join(map(str,k)),v) for k,v in motifs.most_common(100)],
        columns=["motif","count"]
    )
    st.dataframe(top,use_container_width=True)

with tabs[5]:
    st.subheader("H1–H100 geçmiş görünüm haritası")
    n=st.number_input("Sayı seç",1,80,23,1,key="hnum")
    idx=st.slider("Hedef çekiliş indeksi",100,len(df)-1,len(df)-1)
    hist=[]
    for h in range(1,101):
        hist.append({"H":h,"present":int(n in df.at[idx-h,"nums"])})
    hdf=pd.DataFrame(hist)
    st.dataframe(hdf,use_container_width=True,height=450)
    st.write("Hedef:",df.at[idx,"draw"],df.at[idx,"dt"])
    st.write("REAL20 mi?", "EVET" if n in df.at[idx,"nums"] else "HAYIR")

with tabs[6]:
    st.subheader("REAL20 / NEGATIVE60 ritim karşılaştırması")
    panel=h_pattern_panel(df,100)
    g=st.number_input("Gap since last seen",1,101,4,1,key="cmpgap")
    z=panel[panel.gap_since==g]
    if len(z):
        st.metric("REAL20 oranı",f"%{100*z.real20.mean():.2f}",f"{z.real20.sum()}/{len(z)}")
        st.write("Taban: %25")
        st.dataframe(
            z.groupby(["f8","f24"]).agg(
                aday=("real20","size"),
                real20=("real20","sum"),
                oran=("real20","mean")
            ).reset_index().assign(oran=lambda d:(100*d.oran).round(2))
            .sort_values(["oran","aday"],ascending=False).head(100),
            use_container_width=True
        )
    else:
        st.warning("Bu gap için gözlem yok.")

with tabs[7]:
    st.subheader("Walk-forward ritim testi")
    g=st.number_input("Test gap",1,100,4,1,key="wfg")
    reps=st.number_input("Kaç ardışık aynı gap sonrası?",1,8,2,1,key="wfr")
    events=[]
    for n in range(1,81):
        pos=np.flatnonzero(X[:,n-1])
        gaps=np.diff(pos)
        for i in range(reps-1,len(gaps)-1):
            if np.all(gaps[i-reps+1:i+1]==g):
                target_idx=pos[i+2]
                events.append({
                    "date":df.at[target_idx,"dt"].date(),
                    "number":n,
                    "continued":int(gaps[i+1]==g),
                    "next_gap":int(gaps[i+1])
                })
    ev=pd.DataFrame(events)
    if ev.empty:
        st.warning("Yeterli olay yok.")
    else:
        hit=int(ev.continued.sum())
        st.metric("Devam",f"%{100*ev.continued.mean():.2f}",f"{hit}/{len(ev)}")
        day=ev.groupby("date").agg(
            opportunities=("continued","size"),
            continued=("continued","sum"),
            rate=("continued","mean")
        ).reset_index()
        day["rate_pct"]=(100*day.rate).round(2)
        st.dataframe(day,use_container_width=True)
        st.line_chart(day.set_index("date")["rate_pct"])

st.divider()
st.caption("Araştırma prensibi: sinyal yalnız yeterli destek ve kronolojik walk-forward doğrulama sonrası uzman kuralına dönüşür.")
